const allFormData = $('Map & Validate Form Data').all();
const customers = $input.all();
const apiKey = $('Partner Variables').first().json.api_key;
const userEmail = allFormData[0].json.userEmail || '';

let matchedOrgId = null;

for (const customer of customers) {
  const customerId = customer.json.id;

  const response = await helpers.httpRequest({
    method: 'GET',
    url: `https://us-central1-the-byway-248217.cloudfunctions.net/reportApi/api/v1/reports/users?customerId=${customerId}`,
    headers: { 
      'x-api-key': apiKey,
      'accept': 'application/json'
    }
  });

  const match = response.find(u => 
    u.email && u.email.toLowerCase().trim() === userEmail.toLowerCase().trim()
  );

  if (match) {
    matchedOrgId = customerId;
    break;
  }
}

if (!matchedOrgId) {
  throw new Error(`Email not found: "${userEmail}". Please contact your MSP.`);
}

// Return ONE item with countries as array — expand after POST
return [{
  json: {
    ...allFormData[0].json,
    orgId: matchedOrgId,
    allCountries: allFormData.map(item => ({
      country: item.json.country,
      countryCode: item.json.countryCode,
      suppressionName: item.json.suppressionName,
      startDate: item.json.startDate,
      endDate: item.json.endDate
    }))
  }
}];

const clientId = 'Your CLIENT ID';
const tenantId = 'Your TENANT ID';
const redirectUri = 'https://[your-n8n-instance].app.n8n.cloud/webhook/auth/callback';
const scope = 'openid profile email User.Read';
