const items = $('Map & Validate Form Data').all();
const first = items[0].json;
const userName   = first.userName;
const userEmail  = first.userEmail;
const departure  = first.departure;
const returnDate = first.returnDate;
const notes      = first.notes;

// Format dates for display
const formatDate = (dateStr) => new Date(dateStr + 'T00:00:00Z')
  .toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric', timeZone: 'UTC' });

const departureFormatted = formatDate(departure);
const returnFormatted    = formatDate(returnDate);

// Build country list for email
const countryLines = items.map((item, i) => 
  `  ${i + 1}. ${item.json.country}`
).join('\n');

const emailBody = `Your vacation suppression has been successfully created in SaaS Alerts.

Details:
- Name: ${userName}
- Email: ${userEmail}
- Departure: ${departureFormatted}
- Return: ${returnFormatted}${notes ? `\n- Notes: ${notes}` : ''}

Countries covered (${items.length}):
${countryLines}

Alerts for your account will be suppressed during this period and will automatically resume when the suppression expires.`;

return [{ json: { emailBody, userEmail, userName } }];

const profile = $('HTTP – MS Graph profile').first().json;

if (!profile.mail && !profile.userPrincipalName) {
  return [{ json: { valid: false, reason: 'No email found on Microsoft profile.' } }];
}

const userEmail = profile.mail || profile.userPrincipalName;

return [{ json: { 
  valid: true,
  userEmail,
  displayName: profile.displayName
} }];

const profile = $('Validate User').first().json;

if (!profile.valid) {
  return [{ json: { token: null, error: profile.reason } }];
}

const token = Buffer.from(JSON.stringify({
  email: profile.userEmail,
  name: profile.displayName,
  expires: Date.now() + (30 * 60 * 1000)
})).toString('base64');

return [{ json: { token, userEmail: profile.userEmail } }];

const data = $input.first().json;

return data.allCountries.map(c => ({
  json: {
    userName: data.userName,
    userEmail: data.userEmail,
    country: c.country,
    countryCode: c.countryCode,
    departure: data.departure,
