    startDate: c.startDate,
    endDate: c.endDate,
    suppressionName: c.suppressionName,
    orgId: data.orgId,
    notes: data.notes
  }
}));

const query = $input.first().json.query || {};
const token = query.token || '';

let userData = { name: '', email: '' };
try {
  if (token) {
    userData = JSON.parse(Buffer.from(token, 'base64').toString('utf-8'));
  }
