<script>
const token = ${JSON.stringify(token)};
const countries = ${JSON.stringify(countries)};

const destinations = ["Paris, France","Tokyo, Japan","Rome, Italy","Barcelona, Spain","London, UK","Sydney, Australia","Dubai, UAE","New York, USA","Singapore","Amsterdam, Netherlands","Bangkok, Thailand","Prague, Czech Republic","Lisbon, Portugal","Vienna, Austria","Bali, Indonesia","Cape Town, South Africa","Toronto, Canada","Mexico City, Mexico","Buenos Aires, Argentina","Istanbul, Turkey"];
const tickerInner = document.getElementById('tickerInner');
const doubled = [...destinations, ...destinations];
tickerInner.innerHTML = doubled.map(d => '<span class="ticker-item">&#9992; <span>' + d + '</span></span>').join('');

document.querySelectorAll('.combo').forEach(function(combo) {
  const name = combo.getAttribute('data-combo');
  const input = document.getElementById(name + '_input');
  const hidden = document.getElementById(name);
  const list = document.getElementById(name + '_list');
  let activeIndex = -1;
  let filtered = [];

  function renderList(items) {
    filtered = items;
    activeIndex = -1;
    list.innerHTML = items.length === 0
      ? '<div class="combo-empty">No destinations found</div>'
      : items.map((c,i) => '<div class="combo-option" data-index="' + i + '">' + c + '</div>').join('');
  }

  function openList() { list.classList.add('open'); }
  function closeList() { list.classList.remove('open'); }

  input.addEventListener('focus', function() { renderList(countries); openList(); });
  input.addEventListener('input', function() {
    hidden.value = '';
    const q = input.value.toLowerCase();
    renderList(countries.filter(c => c.toLowerCase().indexOf(q) !== -1));
    openList();
  });
  input.addEventListener('keydown', function(e) {
    const opts = list.querySelectorAll('.combo-option');
    if (e.key === 'ArrowDown') { e.preventDefault(); activeIndex = Math.min(activeIndex+1, opts.length-1); updateActive(opts); }
    else if (e.key === 'ArrowUp') { e.preventDefault(); activeIndex = Math.max(activeIndex-1, 0); updateActive(opts); }
    else if (e.key === 'Enter') { e.preventDefault(); if (activeIndex >= 0 && filtered[activeIndex]) selectValue(filtered[activeIndex]); }
    else if (e.key === 'Escape') closeList();
  });
  function updateActive(opts) {
    opts.forEach((o,i) => o.classList.toggle('active', i === activeIndex));
    if (opts[activeIndex]) opts[activeIndex].scrollIntoView({ block: 'nearest' });
  }
  function selectValue(val) { input.value = val; hidden.value = val; closeList(); }
  list.addEventListener('mousedown', function(e) {
    const opt = e.target.closest('.combo-option');
    if (opt) selectValue(filtered[parseInt(opt.getAttribute('data-index'), 10)]);
  });
  document.addEventListener('click', function(e) { if (!combo.contains(e.target)) closeList(); });
});

function showError(msg) {
  const el = document.getElementById('errorBox');
  el.textContent = msg;
  el.style.display = 'block';
}
function clearError() { document.getElementById('errorBox').style.display = 'none'; }

async function submitForm() {
  clearError();
  const comboFields = ['stop1','stop2','stop3','finalDestination'];
  for (const f of comboFields) {
    const v = document.getElementById(f + '_input');
    const h = document.getElementById(f);
    if (v.value && v.value !== h.value) { h.value = ''; v.style.borderColor = '#fca5a5'; }
  }
  for (const f of ['stop1','stop2','stop3']) {
    const v = document.getElementById(f + '_input');
    const h = document.getElementById(f);
    if (v.value.trim() !== '' && h.value === '') {
      showError('Please select a valid destination from the dropdown for all filled stops, or clear the field.');
      return;
    }
  }
  const userName = document.getElementById('userName').value.trim();
  const userEmail = document.getElementById('userEmail').value.trim();
  const stop1 = document.getElementById('stop1').value;
  const stop2 = document.getElementById('stop2').value;
  const stop3 = document.getElementById('stop3').value;
  const finalDestination = document.getElementById('finalDestination').value;
  const departure = document.getElementById('departure').value;
  const returnDate = document.getElementById('returnDate').value;
  const notes = document.getElementById('notes').value.trim();
  if (!userEmail) { showError('Please enter your work email.'); return; }
  if (!finalDestination || !departure || !returnDate) { showError('Please fill in all required fields and select a destination from the dropdown.'); return; }
  const today = new Date().toISOString().split('T')[0];
  if (departure < today) { showError('Departure date cannot be in the past.'); return; }
  if (returnDate < departure) { showError('Return date cannot be before your departure date.'); return; }
  const payload = {
    "First and Last Name": userName,
    "Work Email": userEmail,
    "First Stop (optional)": stop1,
    "Second Stop (optional)": stop2,
    "Third Stop (optional)": stop3,
    "Final Destination": finalDestination,
    "Departure Date": departure,
    "Return Date": returnDate,
    "Additional Notes": notes,
    "submittedAt": new Date().toISOString(),
    "formMode": "production",
    "formQueryParameters": { "token": token }
  };
  const btn = document.getElementById('submitBtn');
  btn.disabled = true;
  btn.innerHTML = '<span>&#8987;</span> Submitting...';
  try {
    const response = await fetch(window.location.pathname.replace('/landing','/submit'), {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    });
    const result = await response.json();
    if (result.success) {
      document.getElementById('formView').style.display = 'none';
      document.getElementById('successView').style.display = 'block';
    } else {
      showError(result.message || 'Something went wrong. Please try again.');
      btn.disabled = false;
      btn.innerHTML = '<span>&#9992;</span> Submit travel request';
    }
  } catch(e) {
    showError('Submission failed. Please contact your MSP for assistance.');
    btn.disabled = false;
    btn.innerHTML = '<span>&#9992;</span> Submit travel request';
  }
}
</script>
